<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { AlertTriangle, CheckCircle2, Loader2, RefreshCw, ZoomIn } from 'lucide-vue-next'
import { api } from '@/services/api'
import { toast } from '@/services/toast'
import type { DocumentDetail, DocumentLineItem } from '@/types/api'

const route = useRoute(); const router = useRouter(); const id = Number(route.params.id)
const detail = ref<DocumentDetail | null>(null); const loading = ref(true); const saving = ref(false); const error = ref(''); const previewUrl = ref('')
const form = reactive({ company_name: '', invoice_number: '', invoice_date: '', merchant_name: '', receipt_number: '', transaction_date: '', transaction_time: '', subtotal: '', tax_amount: '', total_amount: '', currency: '', line_items: [] as DocumentLineItem[] })
const isReceipt = computed(() => detail.value?.document_type === 'receipt')
const confidence = (name: string) => detail.value?.fields[name]?.confidence || 'low'
const source = (name: string) => detail.value?.fields[name]?.text || ''
const isPdf = computed(() => previewUrl.value.includes('application/pdf'))
const ocrNotice = computed(() => {
  if (!detail.value) return null
  if (detail.value.ocr_status === 'provider_unavailable') return { title: 'Image OCR is not available in this environment.', body: 'Tesseract OCR could not be found. Install Tesseract and restart DataBridge.' }
  if (detail.value.ocr_status === 'failed') return { title: 'DataBridge could not extract text from this image.', body: 'Retry or enter the invoice details manually.' }
  if (detail.value.ocr_status === 'unsupported') return { title: 'This PDF appears to contain scanned pages and could not be read as text.', body: detail.value.ocr_message || 'Image-based PDF OCR is not available yet.' }
  return null
})
function apply(result: DocumentDetail) { detail.value = result; for (const key of ['company_name','invoice_number','invoice_date','merchant_name','receipt_number','transaction_date','transaction_time','subtotal','tax_amount','total_amount','currency'] as const) form[key] = result.fields[key]?.value || ''; form.line_items = result.line_items.map(row => ({ ...row })) }
async function load() { loading.value = true; error.value = ''; try { const [result, blob] = await Promise.all([api.getDocument(id), api.getDocumentPreview(id)]); apply(result); if (previewUrl.value) URL.revokeObjectURL(previewUrl.value); previewUrl.value = URL.createObjectURL(blob) } catch (e: any) { error.value = e.message || 'Could not load this document.' } finally { loading.value = false } }
async function changeType(event: Event) { const type = (event.target as HTMLSelectElement).value as 'invoice'|'receipt'; saving.value = true; try { apply(await api.parseDocumentAs(id, type)); toast.success(`Parsed as ${type}`) } catch (e:any) { toast.error(e.message || 'Could not change document type') } finally { saving.value = false } }
async function reprocess() { if (!confirm('Refresh the extracted suggestions? Your unsaved edits will be replaced.')) return; saving.value = true; try { await api.reprocessDocument(id); await load(); toast.success('Document reprocessed') } catch (e: any) { toast.error(e.message || 'Could not reprocess document') } finally { saving.value = false } }
async function confirmImport() { const missing = isReceipt.value ? !form.merchant_name.trim() || !form.receipt_number.trim() : !form.company_name.trim() || !form.invoice_number.trim(); if (missing) { error.value = isReceipt.value ? 'Merchant name and receipt number are required before import.' : 'Company name and invoice number are required before import.'; return } saving.value = true; error.value = ''; try { await api.confirmDocument(id, { ...form, document_type: detail.value?.document_type, total_amount: form.total_amount || null, subtotal: form.subtotal || null, tax_amount: form.tax_amount || null, invoice_date: form.invoice_date || null, transaction_date: form.transaction_date || null, currency: form.currency || null }); toast.success(`${isReceipt.value ? 'Receipt' : 'Invoice'} imported`); router.push('/history') } catch (e: any) { error.value = e.message || 'Import could not be confirmed.'; if (error.value.toLowerCase().includes('duplicate')) toast.warning(`Possible duplicate ${isReceipt.value ? 'receipt' : 'invoice'}`) } finally { saving.value = false } }
function addLine() { form.line_items.push({ description: '', quantity: null, unit_price: null, tax_rate: null, tax_amount: null, amount: null }) }
onMounted(load); onBeforeUnmount(() => { if (previewUrl.value) URL.revokeObjectURL(previewUrl.value) })
</script>
<template>
  <main class="document-review container">
    <header><div><p class="eyebrow">DOCUMENT INGESTION</p><h1>Review document</h1><p>Please verify the extracted values before importing.</p></div><div class="type-controls"><label>Document type <select :value="detail?.document_type" :disabled="saving" @change="changeType"><option value="invoice">Invoice</option><option value="receipt">Receipt</option></select></label><span class="status">{{ detail?.status?.replace('_', ' ') || 'Loading' }}</span></div></header>
    <section v-if="loading" class="glass-card loading"><Loader2 class="animate-spin" /> Processing document…</section>
    <section v-else-if="error && !detail" class="glass-card notice error"><p>{{ error }}</p><button class="btn btn-secondary" @click="load">Retry</button></section>
    <section v-else-if="detail" class="review-grid">
      <article class="glass-card preview"><h2>Original document</h2><iframe v-if="isPdf" :src="previewUrl" title="Document preview" /><img v-else :src="previewUrl" alt="Uploaded document preview" /><p class="muted"><ZoomIn :size="14" /> Browser preview supports normal zoom. {{ detail.processing_method === 'ocr_required' ? 'This document needs an OCR provider or manual entry.' : '' }}</p></article>
      <article class="glass-card form"><div class="form-heading"><div><h2>Extracted {{ isReceipt ? 'receipt' : detail.document_type === 'invoice' ? 'invoice' : 'document' }}</h2><p>Fields marked low need special attention.</p></div><button class="btn btn-secondary" :disabled="saving" @click="reprocess"><RefreshCw :size="16" /> Reprocess</button></div>
        <div v-if="ocrNotice" class="notice warning"><AlertTriangle :size="18" /><div><strong>{{ ocrNotice.title }}</strong><p>{{ ocrNotice.body }}</p></div></div>
        <div v-if="detail.warnings.length" class="notice warning"><AlertTriangle :size="18" /><div><strong>Needs review</strong><ul><li v-for="warning in detail.warnings" :key="warning">{{ warning }}</li></ul></div></div>
        <div v-if="error" class="notice error">{{ error }}</div>
        <div v-if="isReceipt" class="fields">
          <label :class="`confidence-${confidence('merchant_name')}`"><span>Merchant name <em>{{ confidence('merchant_name') }}</em></span><input v-model="form.merchant_name" /><small v-if="source('merchant_name')">Source: {{ source('merchant_name') }}</small></label>
          <label :class="`confidence-${confidence('receipt_number')}`"><span>Receipt number <em>{{ confidence('receipt_number') }}</em></span><input v-model="form.receipt_number" /><small v-if="source('receipt_number')">Source: {{ source('receipt_number') }}</small></label>
          <label :class="`confidence-${confidence('transaction_date')}`"><span>Transaction date <em>{{ confidence('transaction_date') }}</em></span><input v-model="form.transaction_date" type="date" /></label><label><span>Transaction time</span><input v-model="form.transaction_time" /></label>
          <label :class="`confidence-${confidence('currency')}`"><span>Currency <em>{{ confidence('currency') }}</em></span><input v-model="form.currency" /></label><label><span>Subtotal</span><input v-model="form.subtotal" type="number" step="0.01" /></label><label><span>Tax</span><input v-model="form.tax_amount" type="number" step="0.01" /></label><label><span>Total</span><input v-model="form.total_amount" type="number" step="0.01" /></label>
        </div>
        <div v-else class="fields"><label v-for="item in [['company_name','Company name'],['invoice_number','Invoice number'],['invoice_date','Invoice date'],['currency','Currency'],['total_amount','Total amount']]" :key="item[0]" :class="`confidence-${confidence(item[0])}`"><span>{{ item[1] }} <em>{{ confidence(item[0]) }}</em></span><input v-model="form[item[0] as 'company_name']" :type="item[0] === 'invoice_date' ? 'date' : item[0] === 'total_amount' ? 'number' : 'text'" /><small v-if="source(item[0])">Source: {{ source(item[0]) }}</small></label></div>
        <h3>Line items</h3><p v-if="!form.line_items.length" class="muted">No line items detected. You can still import the invoice header.</p><div class="table-wrap" v-else><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit price</th><th>Tax rate</th><th>Tax amount</th><th>Amount</th><th></th></tr></thead><tbody><tr v-for="(line,index) in form.line_items" :key="index"><td><input v-model="line.description" /></td><td><input v-model="line.quantity" /></td><td><input v-model="line.unit_price" /></td><td><input v-model="line.tax_rate" /></td><td><input v-model="line.tax_amount" /></td><td><input v-model="line.amount" /></td><td><button class="btn btn-secondary" aria-label="Delete line item" @click="form.line_items.splice(index,1)">×</button></td></tr></tbody></table></div>
        <div class="actions"><button class="btn btn-secondary" @click="addLine">Add line item</button><button class="btn btn-primary" :disabled="saving" @click="confirmImport"><Loader2 v-if="saving" class="animate-spin" :size="16" /><CheckCircle2 v-else :size="16" /> Confirm & Import</button></div>
      </article>
    </section>
  </main>
</template>
<style scoped>
.document-review{padding-block:2rem}.document-review header,.form-heading,.actions,.type-controls{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start}.type-controls{align-items:center}.type-controls label{display:grid;gap:.25rem;color:var(--text-secondary);font-size:.75rem}.type-controls select{padding:.4rem .6rem;border:1px solid var(--border-medium);border-radius:var(--radius-sm);background:var(--bg-surface);color:var(--text-primary)}.eyebrow{color:var(--accent-brand);font-weight:700;font-size:.75rem;letter-spacing:.08em}.document-review h1,.document-review h2{margin:.2rem 0}.document-review header p,.muted{color:var(--text-secondary)}.status{padding:.4rem .75rem;border-radius:999px;background:var(--status-warning-bg);color:var(--status-warning);text-transform:capitalize}.review-grid{display:grid;grid-template-columns:minmax(300px,1fr) minmax(400px,1fr);gap:1.25rem;margin-top:1.5rem}.preview,.form,.loading{padding:1.25rem}.preview iframe,.preview img{width:100%;height:68vh;border:0;object-fit:contain;background:var(--bg-subtle);margin-top:1rem}.preview .muted{display:flex;gap:.4rem;align-items:center}.notice{padding:.85rem;margin:1rem 0;border-radius:var(--radius-sm);display:flex;gap:.6rem}.warning{background:var(--status-warning-bg);color:var(--status-warning);border:1px solid var(--status-warning-border)}.error{background:var(--status-error-bg);color:var(--status-error);border:1px solid var(--status-error-border)}.fields{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.fields label{display:grid;gap:.3rem}.fields em{font-style:normal;text-transform:capitalize;font-size:.72rem}.fields input,table input{width:100%;box-sizing:border-box;padding:.55rem;border:1px solid var(--border-medium);border-radius:var(--radius-sm);background:var(--bg-surface);color:var(--text-primary)}.confidence-low input{border-color:var(--status-error)}.confidence-medium input{border-color:var(--status-warning)}small{color:var(--text-muted)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:.35rem;text-align:left;white-space:nowrap}.actions{margin-top:1.25rem;align-items:center}.animate-spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:850px){.review-grid{grid-template-columns:1fr}.preview iframe,.preview img{height:48vh}.fields{grid-template-columns:1fr}.document-review header{flex-direction:column}}
</style>
